void quadrado(int N){

    int linha,coluna,soma;
    soma = 0;

    if (N>=2) {

        for (coluna=1; coluna<=N; coluna++) {
            for (linha=1; linha<=N; linha++) {
                printf("%d\t",linha+soma);
            }
